## Code Example

```javascript
// Pseudo-test: ensure idempotent consumer
let lastProcessed = new Map();
async function process(event) {
  const key = event.id;
  if (lastProcessed.has(key)) {
    return { status: 'duplicate', result: lastProcessed.get(key) };
  }
  const result = await processEvent(event);
  lastProcessed.set(key, result);
  return { status: 'processed', result };
}
```

